let db;
async function database(){if(db)return db;db=await new Promise((resolve,reject)=>{const r=indexedDB.open('teacher-desk-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('File storage unavailable. Enable browser storage and retry.'));});return db;}
export async function storeFiles(list){if(!list.length)return [];const out=[];const d=await database();for(const file of list){if(file.size>25*1024*1024)throw Error('Each file must be 25 MB or smaller.');const id=crypto.randomUUID();await new Promise((resolve,reject)=>{const t=d.transaction('files','readwrite');t.objectStore('files').put(file,id);t.oncomplete=resolve;t.onerror=()=>reject(Error('File could not be saved. Browser storage may be full.'));});out.push({id,name:file.name,size:file.size,type:file.type});}return out;}
export async function getFile(id){const d=await database();return new Promise((resolve,reject)=>{const r=d.transaction('files').objectStore('files').get(id);r.onsuccess=()=>r.result?resolve(r.result):reject(Error('This file is unavailable in this browser.'));r.onerror=()=>reject(Error('Could not read file.'));});}
